import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    const current = containerRef.current;
    if (!current) return;

    // Clear previous widget if it exists
    current.innerHTML = '';

    // Create widget container
    const widgetContainer = document.createElement('div');
    widgetContainer.className = 'tradingview-widget-container';

    // Create the widget placeholder
    const widgetDiv = document.createElement('div');
    widgetDiv.className = 'tradingview-widget-container__widget';
    widgetContainer.appendChild(widgetDiv);

    // Create config script
    const configScript = document.createElement('script');
    configScript.type = 'application/json';
    configScript.textContent = JSON.stringify({
      symbol: 'NSE:NIFTY',
      width: '100%',
      height: '350',
      locale: 'en',
      dateRange: '1M',
      colorTheme: 'light',
      trendLineColor: '#14C4B5',
      underLineColor: 'rgba(20, 196, 181, 0.3)',
      underLineBottomColor: 'rgba(20, 196, 181, 0)',
      isTransparent: false,
      autosize: false
    });
    widgetContainer.appendChild(configScript);

    // Create widget loader script
    const loaderScript = document.createElement('script');
    loaderScript.type = 'text/javascript';
    loaderScript.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
    loaderScript.async = true;
    widgetContainer.appendChild(loaderScript);

    current.appendChild(widgetContainer);

    return () => {
      if (current) {
        current.innerHTML = '';
      }
    };
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
